def build_model(data=None):
    d = data or DATA
    nodes = d["nodes"]
    src = d["source"]
    snk = d["sink"]
    cap = d["cap"]

    arcs = list(cap.keys())
    out_arcs = {n: [j for (i, j) in arcs if i == n] for n in nodes}
    in_arcs = {n: [i for (i, j) in arcs if j == n] for n in nodes}
    internal_nodes = [n for n in nodes if n != src and n != snk]

    m = pyo.ConcreteModel()

    m.Arcs = pyo.Set(initialize=arcs, dimen=2)
    m.Internal = pyo.Set(initialize=internal_nodes)

    def _cap_rule(mdl, i, j):
        return (0, cap[(i, j)])

    m.x = pyo.Var(m.Arcs, domain=pyo.NonNegativeReals,
                  bounds=lambda mdl, i, j: (0, cap[(i, j)]))

    # Flow conservation at internal nodes: inflow == outflow
    def conservation_rule(mdl, n):
        return (sum(mdl.x[i, n] for i in in_arcs[n])
                - sum(mdl.x[n, j] for j in out_arcs[n])) == 0

    m.conservation = pyo.Constraint(m.Internal, rule=conservation_rule)

    # Quantity delivered = flow reaching sink
    def delivered_expr(mdl):
        return sum(mdl.x[i, snk] for i in in_arcs[snk])

    def source_now(mdl):
        return sum(mdl.x[src, j] for j in out_arcs[src])

    m.obj = pyo.Objective(expr=delivered_expr(m), sense=pyo.maximize)

    return m
